import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  // Get the JWT token from cookies
  const token = request.cookies.get('auth-token')?.value

  // Define public paths that don't require authentication
  const publicPaths = ['/login', '/register', '/api/auth']
  const isPublicPath = publicPaths.some(path => 
    request.nextUrl.pathname.startsWith(path)
  )

  // If the path is public, allow access
  if (isPublicPath) {
    return NextResponse.next()
  }

  // If no token is found, redirect to login
  if (!token) {
    const loginUrl = new URL('/login', request.url)
    // Add the original path as a query parameter for redirect after login
    loginUrl.searchParams.set('from', request.nextUrl.pathname)
    return NextResponse.redirect(loginUrl)
  }

  // Validate the JWT token
  try {
    // In a real application, you would verify the JWT signature and expiration
    // This is a basic validation - in production, use a proper JWT library
    const isValidToken = validateJWT(token)

    if (!isValidToken) {
      // Token is invalid, redirect to login
      const loginUrl = new URL('/login', request.url)
      loginUrl.searchParams.set('from', request.nextUrl.pathname)
      return NextResponse.redirect(loginUrl)
    }

    // Token is valid, allow access
    return NextResponse.next()

  } catch (error) {
    // If token validation fails, redirect to login
    const loginUrl = new URL('/login', request.url)
    loginUrl.searchParams.set('from', request.nextUrl.pathname)
    return NextResponse.redirect(loginUrl)
  }
}

// Helper function to validate JWT token
// In production, you should use a proper JWT library like 'jsonwebtoken' or 'jose'
function validateJWT(token: string): boolean {
  try {
    // Basic JWT structure validation
    const parts = token.split('.')
    if (parts.length !== 3) {
      return false
    }

    // Decode the payload (without verifying signature for this example)
    const payload = JSON.parse(atob(parts[1]))

    // Check if token is expired
    const now = Math.floor(Date.now() / 1000)
    if (payload.exp && payload.exp < now) {
      return false
    }

    // Additional validation can be added here
    // For example: check issuer, audience, etc.

    return true
  } catch (error) {
    return false
  }
}

// Configure which paths the middleware should run on
export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes) - we'll handle API auth separately if needed
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico, sitemap.xml, robots.txt (metadata files)
     */
    '/((?!api|_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)',
  ],
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

interface PostData {
  title: string;
  content: string;
}

export function CreatePostForm() {
  const [postData, setPostData] = useState<PostData>({
    title: "",
    content: "",
  });

  // Check if both fields are filled to enable the publish button
  const isPublishDisabled = postData.title.trim() === "" || postData.content.trim() === "";

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPostData(prev => ({
      ...prev,
      title: e.target.value,
    }));
  };

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setPostData(prev => ({
      ...prev,
      content: e.target.value,
    }));
  };

  const handlePublish = () => {
    if (!isPublishDisabled) {
      // Here you would typically send the data to your backend
      console.log("Publishing post:", postData);

      // Show success message or navigate away
      alert("Post published successfully!");

      // Reset form after publishing
      setPostData({ title: "", content: "" });
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-3xl font-bold tracking-tight">Create New Post</h1>
        <p className="text-muted-foreground">
          Fill in the title and content below to create a new post.
        </p>
      </div>

      <div className="space-y-4">
        {/* Title Input Field */}
        <div className="space-y-2">
          <Label htmlFor="title">Title</Label>
          <Input
            id="title"
            placeholder="Enter your post title..."
            value={postData.title}
            onChange={handleTitleChange}
            className="w-full"
          />
          <p className="text-sm text-muted-foreground">
            {postData.title.length}/100 characters
          </p>
        </div>

        {/* Content Textarea Field */}
        <div className="space-y-2">
          <Label htmlFor="content">Content</Label>
          <Textarea
            id="content"
            placeholder="Write your post content here..."
            value={postData.content}
            onChange={handleContentChange}
            className="min-h-[200px] w-full resize-none"
          />
          <p className="text-sm text-muted-foreground">
            {postData.content.length}/5000 characters
          </p>
        </div>

        {/* Form Status */}
        <div className="flex items-center justify-between text-sm">
          <div className="text-muted-foreground">
            {isPublishDisabled ? (
              <span className="text-orange-600">
                Please fill in both title and content to publish
              </span>
            ) : (
              <span className="text-green-600">
                Ready to publish!
              </span>
            )}
          </div>

          <div className="text-muted-foreground">
            {postData.title.trim() !== "" && "✓ Title filled"}
            {postData.content.trim() !== "" && "✓ Content filled"}
          </div>
        </div>

        {/* Publish Button */}
        <div className="pt-4">
          <Button
            onClick={handlePublish}
            disabled={isPublishDisabled}
            className="w-full"
            size="lg"
          >
            {isPublishDisabled ? "Complete form to publish" : "Publish Post"}
          </Button>
        </div>
      </div>

      {/* Preview Section (Optional) */}
      <div className="mt-8 p-4 border rounded-lg bg-muted/50">
        <h3 className="text-lg font-semibold mb-2">Preview</h3>
        <div className="space-y-2">
          {postData.title ? (
            <h4 className="text-xl font-medium">{postData.title}</h4>
          ) : (
            <p className="text-muted-foreground italic">Title will appear here...</p>
          )}
          {postData.content ? (
            <p className="whitespace-pre-wrap">{postData.content}</p>
          ) : (
            <p className="text-muted-foreground italic">Content will appear here...</p>
          )}
        </div>
      </div>
    </div>
  );
}

// Alternative simpler version without labels and preview
export function SimpleCreatePostForm() {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  const isPublishDisabled = title.trim() === "" || content.trim() === "";

  const handlePublish = () => {
    if (!isPublishDisabled) {
      console.log("Publishing post:", { title, content });
      alert("Post published successfully!");
      setTitle("");
      setContent("");
    }
  };

  return (
    <div className="max-w-xl mx-auto p-6 space-y-4">
      <h1 className="text-2xl font-bold">Create Post</h1>

      <Input
        placeholder="Post title..."
        value={title}
        onChange={(e) => setTitle(e.target.value)}
        className="w-full"
      />

      <Textarea
        placeholder="Post content..."
        value={content}
        onChange={(e) => setContent(e.target.value)}
        className="min-h-[150px] w-full"
      />

      <Button
        onClick={handlePublish}
        disabled={isPublishDisabled}
        className="w-full"
      >
        {isPublishDisabled ? "Fill both fields to publish" : "Publish"}
      </Button>
    </div>
  );
}

